entries[374501] = { ["name"] = "Choker of Shielding", ["text"] = "2 sec cast 3\nTools: Jeweler's Tools\nReagents:\nShimmering Clasp (2), Illimited Diamond , Elemental Harmony , Spark (#247)\nOptional Reagents:\nDrop:\nAssault of the Zaqali\nZone:\nAberrus, the Shadowed Crucible\nRecipe:\nPurchasable on the Auction House\n\nChoker of Shielding\nBinds when picked up\nNeck\n+234 Stamina\n+ 360 Random Stat 1\n+ 360 Random Stat 2\nUse: Drain the elemental energies from you and your gems, sacrificing 31 from each of their associated stats to shield you for 13907 per gem socketed for 10 sec.\n\nThese stats are returned to you when the shield is broken or expires. (3 Min Cooldown)" }
entries[374502] = { ["name"] = "Narcissist's Sculpture", ["text"] = "2 sec cast\nTools: Jeweler's Tools\nReagents:\nAwakened Fire , Shimmering Clasp , Vibrant Emerald , Glossy Stone (2), Silken Gemdust\nOptional Reagents:\nPolishing Cloth (#182) , Lesser Illustrious Insight (#92)\nSpecialization:\nSetting\n\nNarcissist's Sculpture\nBinds when picked up\n\nUse: Place a luxurious statue of yourself nearby which increases your size and Primary Stat while you admire your glorious self. Try not to let it go to your head.\n\nCan only be used on the Dragon Isles." }
