entries[374506] = { ["name"] = "Revitalizing Red Carving", ["text"] = "2 sec cast\nTools: Jeweler's Tools\nReagents:\nShimmering Clasp , Queen's Ruby , Glossy Stone (2), Silken Gemdust\nOptional Reagents:\nPolishing Cloth (#182) , Lesser Illustrious Insight (#92)\nProfession Trainer:\nDragon Isles Jewelcrafting (25)\nCost:\n1\n\nRevitalizing Red Carving\nBinds when picked up\n\nUse: Place a glorious draconic statue on the ground nearby where it will heal you for a short time before its power fades.\n\nCan only be used on the Dragon Isles.\n60" }
entries[374508] = { ["name"] = "Statue of Tyr's Herald", ["text"] = "2 sec cast\nTools: Jeweler's Tools\nReagents:\nGlowing Titan Orb , Shimmering Clasp , Mystic Sapphire , Glossy Stone (2), Silken Gemdust\nOptional Reagents:\nPolishing Cloth (#182) , Lesser Illustrious Insight (#92)\nSpecialization:\nSetting - Stone (15)\n\nStatue of Tyr's Herald\nBinds when picked up\n\nUse: Place a remarkable statue of a Titan Keeper nearby for 2 min. Players who /kneel before the statue will have their worthiness judged.\n\nA player's worthiness can only be judged once every 1 hour. Can only be used on the Dragon Isles." }
entries[374509] = { ["name"] = "Djaradin's \"Pinata\"", ["text"] = "2 sec cast\nTools: Jeweler's Tools\nReagents:\nAwakened Ire , Shimmering Clasp (3), Sundered Onyx (6), Glossy Stone (9), Silken Gemdust (2)\nOptional Reagents:\nPolishing Cloth (#182) , Lesser Illustrious Insight (#92)\nVendor:\nEraneth\nZone:\nValdrakken\nCost:\n3\n\nDjaradin's \"Pinata\"\n\nUse: Place an intimidating statue of a decapitated dragon onto the battlefield nearby which can be attacked by players of either faction. Once destroyed, it will drop a random battleground buff that anyone can claim.\n\nCan only be used in War Mode on the Dragon Isles and in unrated battlegrounds." }
