entries[375150] = { ["name"] = "Venom-Steeped Stompers", ["text"] = "2 sec cast 3\nReagents:\nCacophonous Thunderscale (6), Adamant Scales (150), Stonecrust Hide (18), Spark (#247)\nOptional Reagents:\nThis putrid recipe requires an altar infused with powerful decay magic, rumored to be deep in Brackenhide Hollow.\nDrop:\nDecayed Creatures\nZone:\nBrackenhide Hollow and Surroundings\nRecipe:\nPurchasable on the Auction House\n\nVenom-Steeped Stompers\nBinds when picked up\nFeet Mail\n346 Armor\n+193 [Agility or Intellect]+312 Stamina\n+ 128 Versatility\n+ 205 Mastery\nDurability 80 / 80\nEquip: Toxins course through you, occasionally triggering Potent Venom. While affected by Potent Venom, you lose 203 of your lowest secondary stat and gain 509 of your highest secondary stat for 10 sec.\n\nThese effects are increased by 100% if you equip an item crafted with a Toxified Armor Patch.\n70" }
entries[375151] = { ["name"] = "Acidic Hailstone Treads", ["text"] = "2 sec cast 3\nReagents:\nRockfang Leather (12), Adamant Scales (150), Frostbite Scales (18), Spark (#247)\nOptional Reagents:\nThis putrid recipe requires an altar infused with powerful decay magic, rumored to be deep in Brackenhide Hollow.\nDrop:\nDecayed Creatures\nZone:\nBrackenhide Hollow and Surroundings\nRecipe:\nPurchasable on the Auction House\n\nAcidic Hailstone Treads\nBinds when picked up\nFeet Mail\n346 Armor\n+193 [Agility or Intellect]+312 Stamina\n+ 205 Critical Strike\n+ 150 Mastery\nDurability 80 / 80\nEquip: These boots permeate a deep chill through you, causing your spells and abilities to sometimes deal an additional 2674 Frost damage, but permanently slow your movement speed by 10%.\n\nThese effects are increased by 100% if you equip an item crafted with a Toxified Armor Patch.\n70" }
