entries[375157] = { ["name"] = "Allied Legguards of Sansok Khan", ["text"] = "2 sec cast 3\nReagents:\nCentaur's Trophy Necklace , Adamant Scales (150), Earthshine Scales (20), Spark (#247)\nOptional Reagents:\nVendor:\nQuartermaster Huseng\nZone:\nOhn'ahran Plains\nCost:\n400\n\nAllied Legguards of Sansok Khan\nBinds when picked up\nLegs Mail\n485 Armor\n+257 [Agility or Intellect]+416 Stamina\n+ 280 Critical Strike\n+ 198 Mastery\nDurability 120 / 120\nEquip: Your spells and abilities have a chance to rally you and your 4 closest allies within 30 yards to victory for 10 sec, increasing Versatility by 138 .\n70" }
entries[375159] = { ["name"] = "Fang Adornments", ["text"] = "2 sec cast\nReagents:\nRockfang Leather (2), Pristine Vorquin Horn (2), Aquatic Maw , Mastodon Tusk , Resilient Leather (60), Earthshine Scales (3)\nOptional Reagents:\nLesser Illustrious Insight (#92)\nSpecialization:\nPrimordial Leatherworking - Bestial Primacy (20)\n\nFang Adornments\n61\nOptional Crafting Reagent\n+35 Recipe Difficulty\nProvides the following property: Physical attacks sometimes deal extra physical damage. Also add Unique-Equipped: Embellished (2).\nUsable with: Dragon Isles recipes for most unembellished Epic weapons and off-hands." }
entries[375160] = { ["name"] = "Toxified Armor Patch", ["text"] = "2 sec cast\nReagents:\nAwakened Decay (8), Adamant Scales (60), Stonecrust Hide (2)\nOptional Reagents:\nLesser Illustrious Insight (#92)\nThis putrid recipe requires an altar infused with powerful decay magic, rumored to be deep in Brackenhide Hollow.\nSpecialization:\nPrimordial Leatherworking - Decaying Grasp (20)\n\nToxified Armor Patch\n61\nOptional Crafting Reagent\n+35 Recipe Difficulty\nProvides the following property: Infuses the item with the essence of decay. Also add Unique-Equipped: Embellished (2).\nUsable with: Dragon Isles recipes for most unembellished Epic leather and mail." }
entries[375161] = { ["name"] = "Frosted Armor Kit", ["text"] = "2 sec cast\nReagents:\nAwakened Frost (10), Adamant Scales (60), Frostbite Scales (4)\nOptional Reagents:\nIllustrious Insight (#93)\nVendor:\nSteiz\nZone:\nThe Azure Span\nCobalt Assembly - High\nCost:\n50\n\nUse: Apply a Frosted Armor Kit to your leg armor, permanently increasing its armor by 7. Additionally, the item also gains 8 Agility or Strength.\n61" }
