entries[375166] = { ["name"] = "Illustrious Insight", ["text"] = "2 sec cast\nReagents:\nSpecialization:\nVarious specializations, upon learning to use Illustrious Insight\n\nIllustrious Insight\nBinds when picked up\nUse: Break into 5 Lesser Illustrious Insight.\nFinishing Crafting Reagent\n\nWhen crafting: Increases Skill by 30.\nUsable with: Dragon Isles recipes that are particularly intricate and challenging to craft." }
